from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    ans = 10**30
    prev_ors = set()

    for x in nums:
        cur_ors = {x}

        diff = abs(k - x)
        if diff < ans:
            ans = diff

        for v in prev_ors:
            val = v | x
            cur_ors.add(val)

            diff = abs(k - val)
            if diff < ans:
                ans = diff

        if ans == 0:
            return 0

        prev_ors = cur_ors

    return ans
