MOD = 998244353

def count_valid_colorings(n: int, m: int) -> int:
    x = (m - 1) % MOD
    ans = pow(x, n, MOD)

    if n % 2 == 0:
        return (ans + x) % MOD
    else:
        return (ans - x) % MOD
